  ('e2000000-0000-4000-a000-000000001a06', 'CO-QUI-00136', 7, 541, 'medio', 4, 27, 2026, 'multiple_choice', 'Lei de Hess e entalpia de formação', 'A reação C₂H₄(g) + 3 O₂(g) → 2 CO₂(g) + 2 H₂O(l) tem ΔH = −1.412 kJ por mol de C₂H₄. Qual é a quantidade de calor liberada quando 5 mol de C₂H₄ reagem completamente?', 'O ΔH é proporcional à quantidade que reage: 5 · 1.412 = 7.060 kJ liberados (reação exotérmica).', 'Regra de três: o ΔH dado vale para 1 mol do reagente.', 'Questão autoral da Educa Mais. Referência de estilo: UEMA. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001a07', 'CO-QUI-00137', 7, 541, 'medio', 4, 28, 2026, 'multiple_choice', 'Lei de Hess e entalpia de formação', 'Considere a reação CO(g) + ½ O₂(g) → CO₂(g) e as entalpias de formação: CO: −111 kJ/mol; CO₂: −394 kJ/mol (substâncias simples, como O₂, N₂ e H₂, valem zero). Qual é a variação de entalpia da reação?', 'ΔH = ΣHf(produtos) − ΣHf(reagentes) = (1·(−394)) − (1·(−111)) = −283 kJ. ΔH negativo: reação exotérmica (libera calor).', 'Produtos menos reagentes, multiplicando cada entalpia pelo coeficiente.', 'Questão autoral da Educa Mais. Referência de estilo: UNITINS. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001a08', 'CO-QUI-00138', 7, 541, 'medio', 4, 29, 2026, 'multiple_choice', 'Lei de Hess e entalpia de formação', 'Considere a reação CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(l) e as entalpias de formação: CH₄: −75 kJ/mol; CO₂: −394 kJ/mol; H₂O: −286 kJ/mol (substâncias simples, como O₂, N₂ e H₂, valem zero). Qual é a variação de entalpia da reação?', 'ΔH = ΣHf(produtos) − ΣHf(reagentes) = (1·(−394) + 2·(−286)) − (1·(−75)) = −891 kJ. ΔH negativo: reação exotérmica (libera calor).', 'Produtos menos reagentes, multiplicando cada entalpia pelo coeficiente.', 'Questão autoral da Educa Mais. Referência de estilo: UERJ. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001a09', 'CO-QUI-00139', 7, 541, 'medio', 4, 33, 2026, 'multiple_choice', 'Lei de Hess e entalpia de formação', 'Considere a reação C₂H₅OH(l) + 3 O₂(g) → 2 CO₂(g) + 3 H₂O(l) e as entalpias de formação: C₂H₅OH: −278 kJ/mol; CO₂: −394 kJ/mol; H₂O: −286 kJ/mol (substâncias simples, como O₂, N₂ e H₂, valem zero). Qual é a variação de entalpia da reação?', 'ΔH = ΣHf(produtos) − ΣHf(reagentes) = (2·(−394) + 3·(−286)) − (1·(−278)) = −1.368 kJ. ΔH negativo: reação exotérmica (libera calor).', 'Produtos menos reagentes, multiplicando cada entalpia pelo coeficiente.', 'Questão autoral da Educa Mais. Referência de estilo: UFPE. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
