  ('e2000000-0000-4000-a000-000000001af3', 'CO-QUI-00373', 7, 549, 'medio', 4, 22, 2026, 'multiple_choice', 'Emissões alfa e beta', 'O nuclídeo Po (Z = 84, A = 218) emite 1 partícula alfa e 2 partículas beta. Quais são o número atômico e o número de massa do nuclídeo final?', 'Cada alfa (⁴₂α) tira 2 do Z e 4 do A; cada beta (⁰₋₁β) soma 1 ao Z e não muda o A. Z = 84 − 2·1 + 2 = 84; A = 218 − 4·1 = 214.', 'Alfa: −2 no Z e −4 no A. Beta: +1 no Z.', 'Questão autoral da Educa Mais. Referência de estilo: UNICAMP. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001af4', 'CO-QUI-00374', 7, 549, 'medio', 4, 25, 2026, 'multiple_choice', 'Emissões alfa e beta', 'O nuclídeo Th (Z = 90, A = 232) emite 3 partículas alfa e 4 partículas beta. Quais são o número atômico e o número de massa do nuclídeo final?', 'Cada alfa (⁴₂α) tira 2 do Z e 4 do A; cada beta (⁰₋₁β) soma 1 ao Z e não muda o A. Z = 90 − 2·3 + 4 = 88; A = 232 − 4·3 = 220.', 'Alfa: −2 no Z e −4 no A. Beta: +1 no Z.', 'Questão autoral da Educa Mais. Referência de estilo: UFMG. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001af5', 'CO-QUI-00375', 7, 549, 'medio', 4, 26, 2026, 'multiple_choice', 'Emissões alfa e beta', 'O nuclídeo U (Z = 92, A = 238) emite 2 partículas alfa e 0 partículas beta. Quais são o número atômico e o número de massa do nuclídeo final?', 'Cada alfa (⁴₂α) tira 2 do Z e 4 do A; cada beta (⁰₋₁β) soma 1 ao Z e não muda o A. Z = 92 − 2·2 + 0 = 88; A = 238 − 4·2 = 230.', 'Alfa: −2 no Z e −4 no A. Beta: +1 no Z.', 'Questão autoral da Educa Mais. Referência de estilo: PAS/UnB. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001af6', 'CO-QUI-00376', 7, 549, 'medio', 4, 27, 2026, 'multiple_choice', 'Emissões alfa e beta', 'O nuclídeo Ra (Z = 88, A = 226) emite 1 partícula alfa e 0 partículas beta. Quais são o número atômico e o número de massa do nuclídeo final?', 'Cada alfa (⁴₂α) tira 2 do Z e 4 do A; cada beta (⁰₋₁β) soma 1 ao Z e não muda o A. Z = 88 − 2·1 + 0 = 86; A = 226 − 4·1 = 222.', 'Alfa: −2 no Z e −4 no A. Beta: +1 no Z.', 'Questão autoral da Educa Mais. Referência de estilo: UEMA. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001af7', 'CO-QUI-00377', 7, 550, 'medio', 2, 28, 2026, 'multiple_choice', 'Nomenclatura de hidrocarbonetos', 'Qual é o nome oficial (IUPAC) do hidrocarboneto de cadeia aberta e normal C₃H₆, com a insaturação no carbono 1?', 'Prefixo "prop" = 3 carbonos; infixo "en" indica alceno (uma ligação dupla, CnH2n); sufixo "o" = hidrocarboneto. Propeno: C₃H₆.', 'Prefixo conta os carbonos; infixo an/en/in indica simples, dupla ou tripla.', 'Questão autoral da Educa Mais. Referência de estilo: UNITINS. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001af8', 'CO-QUI-00378', 7, 550, 'medio', 2, 29, 2026, 'multiple_choice', 'Nomenclatura de hidrocarbonetos', 'Qual é a fórmula molecular do butano?', 'Prefixo "but" = 4 carbonos; infixo "an" indica alcano (só ligações simples, CnH2n+2); sufixo "o" = hidrocarboneto. Butano: C₄H₁₀.', 'Prefixo conta os carbonos; infixo an/en/in indica simples, dupla ou tripla.', 'Questão autoral da Educa Mais. Referência de estilo: UERJ. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001af9', 'CO-QUI-00379', 7, 550, 'medio', 2, 33, 2026, 'multiple_choice', 'Nomenclatura de hidrocarbonetos', 'Qual é o nome oficial (IUPAC) do hidrocarboneto de cadeia aberta e normal C₆H₁₀, com a insaturação no carbono 1?', 'Prefixo "hex" = 6 carbonos; infixo "in" indica alcino (uma ligação tripla, CnH2n−2); sufixo "o" = hidrocarboneto. Hexino: C₆H₁₀.', 'Prefixo conta os carbonos; infixo an/en/in indica simples, dupla ou tripla.', 'Questão autoral da Educa Mais. Referência de estilo: UFPE. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001afa', 'CO-QUI-00380', 7, 550, 'medio', 2, 35, 2026, 'multiple_choice', 'Nomenclatura de hidrocarbonetos', 'Qual é o nome oficial (IUPAC) do hidrocarboneto de cadeia aberta e normal C₁₀H₂₀, com a insaturação no carbono 1?', 'Prefixo "dec" = 10 carbonos; infixo "en" indica alceno (uma ligação dupla, CnH2n); sufixo "o" = hidrocarboneto. Deceno: C₁₀H₂₀.', 'Prefixo conta os carbonos; infixo an/en/in indica simples, dupla ou tripla.', 'Questão autoral da Educa Mais. Referência de estilo: UECE. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001afb', 'CO-QUI-00381', 7, 550, 'medio', 2, 36, 2026, 'multiple_choice', 'Nomenclatura de hidrocarbonetos', 'Qual é o nome oficial (IUPAC) do hidrocarboneto de cadeia aberta e normal C₁₀H₁₈, com a insaturação no carbono 1?', 'Prefixo "dec" = 10 carbonos; infixo "in" indica alcino (uma ligação tripla, CnH2n−2); sufixo "o" = hidrocarboneto. Decino: C₁₀H₁₈.', 'Prefixo conta os carbonos; infixo an/en/in indica simples, dupla ou tripla.', 'Questão autoral da Educa Mais. Referência de estilo: UFPA. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001afc', 'CO-QUI-00382', 7, 550, 'medio', 2, 40, 2026, 'multiple_choice', 'Nomenclatura de hidrocarbonetos', 'Qual é a fórmula molecular do pentano?', 'Prefixo "pent" = 5 carbonos; infixo "an" indica alcano (só ligações simples, CnH2n+2); sufixo "o" = hidrocarboneto. Pentano: C₅H₁₂.', 'Prefixo conta os carbonos; infixo an/en/in indica simples, dupla ou tripla.', 'Questão autoral da Educa Mais. Referência de estilo: UFPI. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
